M, C = student.get("Maillon"), student.get("Chaine")
def construit(L):
    c = C()
    c.debut = None
    i = len(L) - 1
    while i >= 0:
        m = M(L[i])
        m.suivant = c.debut
        c.debut = m
        i = i - 1
    return c
def valeurs(c):
    res, m = [], getattr(c, "debut", None)
    while m is not None:
        if len(res) > 200:
            return None  # la chaîne boucle sur elle-même
        res.append(getattr(m, "valeur", None))
        m = getattr(m, "suivant", None)
    return res
def montre(L):
    if L is None:
        return "une chaîne qui tourne en rond (un maillon pointe vers un maillon déjà rencontré)"
    return "la chaîne " + (" → ".join(str(v) for v in L) if L else "vide")
if not isinstance(M, type) or not isinstance(C, type):
    check(False, "les classes `Maillon` et `Chaine` doivent être définies (gardez le code de départ)")
elif not callable(getattr(C, mname, None)):
    check(False, f"la classe `Chaine` doit avoir une méthode `{mname}`")
else:
    for L, args, ret, apres in cases:
        c = construit(L)
        appel = f"`c.{mname}(" + ", ".join(repr(a) for a in args) + f")` avec c = {montre(L)}"
        try:
            r = getattr(c, mname)(*args)
        except Exception as e:
            if type(e).__name__ == "TimeLimit":
                raise
            check(False, f"{appel} provoque une erreur : {erreur(e)}")
            continue
        if ret[0] == "chaine":
            if type(r).__name__ != "Chaine":
                check(False, f"{appel} doit renvoyer une **Chaine**, et non `{r!r}`")
            else:
                check_equal(valeurs(r), ret[1], f"{appel} renvoie {montre(valeurs(r))} au lieu de {montre(ret[1])}")
        else:
            check_equal(r, ret[1], f"{appel} renvoie `{r!r}` au lieu de `{ret[1]!r}`")
        check_equal(valeurs(c), apres, f"après {appel}, c est devenue {montre(valeurs(c))} au lieu de {montre(apres)}")

