FICHE = 'class Fiche:\n    def __init__(self, unnom, untel):\n        self.nom = unnom\n        self.tel = untel\n        self.suivant = None'
REPERTOIRE = 'class Repertoire:\n    def __init__(self):\n        # à la création, le répertoire est vide\n        self.premier = None'
def tel():
    return "06" + "".join(str(randint(0, 9)) for _ in range(8))
def repertoire(n):
    return [(nom, tel()) for nom in sample(PRENOMS, n)]
METHODES = {
    "taille": ("self", "renvoie le nombre de fiches du répertoire",
               "        n = 0\n        courant = self.premier\n        while courant != None:\n            n = n + 1\n            courant = courant.suivant\n        return n"),
    "ajoute_en_tete": ("self, f", "ajoute la fiche `f` (une instance de `Fiche`) **en tête** du répertoire",
                       "        f.suivant = self.premier\n        self.premier = f"),
    "cherche": ("self, nom", "renvoie le numéro de téléphone de la personne `nom`, ou `None` si elle n'est pas dans le répertoire",
                "        courant = self.premier\n        while courant != None:\n            if courant.nom == nom:\n                return courant.tel\n            courant = courant.suivant\n        return None"),
    "supprime": ("self, num_tel", "supprime du répertoire la fiche dont le numéro est `num_tel` (si aucune fiche n'a ce numéro, le répertoire ne change pas)",
                 "        if self.premier == None:\n            return\n        if self.premier.tel == num_tel:\n            # le 2e passe premier\n            self.premier = self.premier.suivant\n        else:\n            courant = self.premier\n            while courant.suivant != None and courant.suivant.tel != num_tel:\n                courant = courant.suivant\n            if courant.suivant != None:\n                courant.suivant = courant.suivant.suivant"),
}
mname = choice(list(METHODES))
params, doc, corps = METHODES[mname]
cases = []
for n in (4, 3, 5, 1, 0):
    L = repertoire(n)
    if mname == "taille":
        cases.append((L, (), len(L), L))
    elif mname == "cherche":
        nom = choice(L)[0] if L and n != 3 else choice([p for p in PRENOMS if p not in [x for x, _ in L]])
        cases.append((L, (nom,), dict(L).get(nom), L))
    elif mname == "ajoute_en_tete":
        nom, t = choice([p for p in PRENOMS if p not in [x for x, _ in L]]), tel()
        cases.append((L, (("fiche", nom, t),), None, [(nom, t)] + L))
    elif mname == "supprime":
        if n == 3 or not L:
            t = "0700000000"
            cases.append((L, (t,), None, L))
        else:
            k = {4: 0, 5: 4, 1: 0}[n] if n != 4 else choice([0, 2])
            t = L[k][1]
            cases.append((L, (t,), None, L[:k] + L[k + 1:]))
if mname == "supprime":
    L = repertoire(5)
    cases.append((L, (L[2][1],), None, L[:2] + L[3:]))
ex_L, ex_args, ex_ret, ex_apres = cases[0]
noms_ex = " → ".join(f"{x} ({t})" for x, t in ex_L)
if mname == "taille":
    ex = f"`R.taille()` renvoie `{ex_ret}`"
elif mname == "cherche":
    ex = f"`R.cherche({ex_args[0]!r})` renvoie `{ex_ret!r}`"
elif mname == "ajoute_en_tete":
    ex = f"après `R.ajoute_en_tete(Fiche({ex_args[0][1]!r}, {ex_args[0][2]!r}))`, le répertoire commence par {ex_args[0][1]}"
else:
    ex = f"après `R.supprime({ex_args[0]!r})`, le répertoire contient " + (" → ".join(x for x, t in ex_apres) or "plus aucune fiche")
starter = FICHE + "\n\n" + REPERTOIRE + f"\n\n    def {mname}({params}):\n        "
ref = FICHE + "\n\n" + REPERTOIRE + f"\n\n    def {mname}({params}):\n" + corps

