F, R = student.get("Fiche"), student.get("Repertoire")
def construit(L):
    r = R()
    r.premier = None
    i = len(L) - 1
    while i >= 0:
        f = F(L[i][0], L[i][1])
        f.suivant = r.premier
        r.premier = f
        i = i - 1
    return r
def fiches(r):
    res, f = [], getattr(r, "premier", None)
    while f is not None:
        if len(res) > 200:
            return None  # le répertoire boucle sur lui-même
        res.append((getattr(f, "nom", None), getattr(f, "tel", None)))
        f = getattr(f, "suivant", None)
    return res
def montre(L):
    if L is None:
        return "une suite de fiches qui tourne en rond (une fiche pointe vers elle-même ou vers une fiche déjà rencontrée)"
    return "[" + ", ".join(str(n) for n, t in L) + "]"
if not isinstance(F, type) or not isinstance(R, type):
    check(False, "les classes `Fiche` et `Repertoire` doivent être définies (gardez le code de départ)")
elif not callable(getattr(R, mname, None)):
    check(False, f"la classe `Repertoire` doit avoir une méthode `{mname}`")
else:
    for L, args, ret, apres in cases:
        r = construit(L)
        objs = [F(a[1], a[2]) if isinstance(a, tuple) and a[0] == "fiche" else a for a in args]
        appel = f"`R.{mname}(" + ", ".join(f"Fiche({a[1]!r}, {a[2]!r})" if isinstance(a, tuple) else repr(a) for a in args) + f")` avec le répertoire {montre(L)}"
        try:
            res = getattr(r, mname)(*objs)
        except Exception as e:
            if type(e).__name__ == "TimeLimit":
                raise
            check(False, f"{appel} provoque une erreur : {erreur(e)}")
            continue
        check_equal(res, ret, f"{appel} renvoie `{res!r}` au lieu de `{ret!r}`")
        check_equal(fiches(r), apres, f"après {appel}, le répertoire contient {montre(fiches(r))} au lieu de {montre(apres)}")

